use std::marker::PhantomPinned;
use std::pin::Pin;

struct SelfReferential {
    data: String,
    ptr: *const String,
    _pin: PhantomPinned,
}

impl SelfReferential {
    fn new(data: String) -> Pin<Box<Self>> {
        let mut s = Self {
            ptr: std::ptr::null(),
            data,
            _pin: PhantomPinned,
        };
        let mut pinned = Box::pin(s);
        unsafe {
            let mut_ref = Pin::as_mut(&mut pinned);
            mut_ref.get_unchecked_mut().ptr = &mut_ref.get_unchecked_mut().data;
        }
        pinned
    }

    fn get_ptr(&self) -> &String {
        unsafe { &*self.ptr }
    }
}

async fn example() -> i32 {
    42
}

fn main() {
    let pinned = SelfReferential::new("Hello".to_string());
    println!("{}", pinned.get_ptr());

    let fut = example();

    println!("Self-referential pointer OK");
}

