#[macro_export]
macro_rules! hashmap {
    ($($key:expr => $val:expr),* $(,)?) => {{
        let mut map = ::std::collections::HashMap::new();
        $(map.insert($key, $val);)*
        map
    }};
}

#[macro_export]
macro_rules! builder {
    ($name:ident { $($field:ident: $ty:ty),* $(,)? }) => {
        struct $name {
            $($field: $ty,)*
        }

        struct $name {
            $($field: Option<$ty>,)*
            _private: (),
        }

        impl $name {
            fn new() -> Self {
                Self {
                    $($field: None,)*
                    _private: (),
                }
            }
            $(fn $field(mut self, val: $ty) -> Self {
                self.$field = Some(val);
                self
            })*
            fn build(self) -> Result<$name, &'static str> {
                Ok($name {
                    $($field: self.$field.ok_or(concat!(
                        stringify!($field), " is required"))?,)*
                })
            }
        }
    };
}

#[macro_export]
macro_rules! compute {
    ($x:expr) => { $x };
    ($x:expr + $($rest:tt)+) => { $x + compute!($($rest)*) };
    ($x:expr * $($rest:tt)+) => { $x * compute!($($rest)*) };
}

fn main() {
    let m = hashmap!(
        "one" => 1,
        "two" => 2,
        "three" => 3,
    );
    println!("Map len: {}", m.len());

    let result = compute!(1 + 2 * 3 + 4);
    println!("Compute: {}", result);
}
